package com.citacloud.app.repositories;
import com.citacloud.app.models.SesionCaja; import org.springframework.data.jpa.repository.*; import jakarta.persistence.LockModeType; import java.util.*;
public interface SesionCajaRepository extends JpaRepository<SesionCaja,UUID>{Optional<SesionCaja> findByEmpresaIdAndSucursalIdAndAbiertoPorAndEstado(UUID e,UUID s,UUID u,String estado); Optional<SesionCaja> findByEmpresaIdAndCajaIdAndEstado(UUID e,UUID cajaId,String estado); Optional<SesionCaja> findByIdAndEmpresaId(UUID id,UUID e); Optional<SesionCaja> findByEmpresaIdAndClaveCierre(UUID e,String clave); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select s from SesionCaja s where s.id=?1 and s.empresaId=?2") Optional<SesionCaja> findForUpdate(UUID id,UUID e); List<SesionCaja> findByEmpresaIdOrderByAbiertoEnDesc(UUID e);}
